import React from "react";
import { gql, useQuery, useMutation } from "@apollo/client";

// ============================================================
// HELPER
// ============================================================
function formatDuration(seconds) {
  if (!seconds && seconds !== 0) return "—";
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, "0");
  return `${m}:${s}`;
}

// ============================================================
// QUERIES & MUTATIONS
// ============================================================
const LIKED_TRACKS = gql`
  query LikedTracks {
    myLikedTracks {
      id
      createdAt
      track {
        id
        title
        duration
        rank
        explicit_lyrics
        artist { name }
        album { title cover_medium }
      }
    }
  }
`;

const UNLIKE_TRACK = gql`
  mutation UnlikeTrack($trackId: ID!) {
    unlikeTrack(trackId: $trackId) {
      acknowledged
    }
  }
`;

// ============================================================
// COMPOSANT
// ============================================================
export default function LikedTracks({ token }) {

  const authHeaders = {
    context: {
      headers: {
        authorization: `Bearer ${token}`,
      },
    },
  };

  const { data, loading, error, refetch } = useQuery(MY_LIKED_TRACKS, {
    ...authHeaders,
  });

  const [unlikeTrack] = useMutation(UNLIKE_TRACK, {
    ...authHeaders,
    onCompleted: () => refetch(),
  });

  // ============================================================
  // STATES
  // ============================================================
  if (!token) return <div className="empty">🔐 Connecte-toi</div>;
  if (loading) return <div className="loading">⏳ Chargement...</div>;
  if (error) return <div className="error">❌ {error.message}</div>;

  const likedTracks = data?.myLikedTracks || [];

  // ============================================================
  // VIEW
  // ============================================================
  return (
    <div>
      <h2>❤️ Mes titres likés</h2>

      <div className="items-grid">
        {likedTracks.map((l) => {
          const t = l.track;

          return (
            <div key={l.id} className="card">

              {t.album?.cover_medium && (
                <img
                  src={t.album.cover_medium}
                  alt={t.title}
                  style={{
                    width: "100%",
                    height: "180px",
                    objectFit: "cover",
                    borderRadius: "4px",
                    marginBottom: "1rem",
                  }}
                  onError={(e) => (e.target.style.display = "none")}
                />
              )}

              <h3>
                {t.explicit_lyrics && (
                  <span style={{
                    background: "#FCEBEB",
                    color: "#A32D2D",
                    fontSize: 10,
                    padding: "2px 6px",
                    borderRadius: 3,
                    marginRight: 6,
                  }}>E</span>
                )}
                {t.title}
              </h3>

              <p>🎤 {t.artist?.name}</p>

              <div className="card-meta">
                <span>⏱️ {formatDuration(t.duration)}</span>
                {t.rank && <span>⭐ {t.rank}</span>}
              </div>

              <div className="card-actions">
                <button
                  onClick={() => unlikeTrack({ variables: { trackId: t.id } })}
                  className="btn-danger"
                >
                  💔 Unlike
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {likedTracks.length === 0 && (
        <div className="empty">📭 Aucun titre liké</div>
      )}
    </div>
  );
}
